values (
  'Original Course', 4, 'changed', 'Changed', 'intermediate',
  'Lá thư gửi chuyên mục Dear Abby: sau 39 năm, chồng của Grace không còn âu yếm bà. Học cách kể chuyện ở quá khứ, thì hiện tại hoàn thành và luyện phản xạ qua Mini-Story.',
  'https://images.unsplash.com/photo-1625690987114-86f5af994b49',
  'Original_Course/104a Changed (main).mp3',
  'Original_Course/104c Changed A (ms).mp3',
  'Original_Course/104b Changed (vocabulary).mp3',
$j$[
  [0,"Changed","Thay đổi"],
  [4,"Dear Abby,","Abby thân mến,"],
  [5.6,"My husband of 39 years no longer hugs me or shows me any affection.","Người chồng đã chung sống với tôi 39 năm không còn ôm tôi hay thể hiện bất kỳ sự âu yếm nào với tôi."],
  [17,"I have seen him through cancer and diabetes.","Tôi đã đồng hành và chăm sóc ông ấy vượt qua bệnh ung thư và tiểu đường."],
  [19.8,"We have four grown children and we have been seeing a therapist for a year and a half.","Chúng tôi có bốn người con đã trưởng thành và đã gặp chuyên gia trị liệu được một năm rưỡi."],
  [26,"He is kind, generous, and friendly,","Ông ấy tử tế, hào phóng và thân thiện,"],
  [38,"but there are no compliments or any of the flirtatious banter we used to enjoy.","nhưng không còn những lời khen hay những câu trêu đùa tán tỉnh mà chúng tôi từng thích thú cùng nhau."],
  [44.8,"He swears he's not having an affair","Ông ấy khẳng định chắc chắn rằng mình không ngoại tình"],
  [48,"and he doesn't know why he has changed.","và ông ấy không biết tại sao mình lại thay đổi."],
  [52.8,"Perhaps you do.","Có lẽ bạn biết lý do."],
  [54.6,"Signed, Grace in Phoenix.","Người ký tên: Grace ở Phoenix."]
]$j$::jsonb,
